        <div data-if="hasLocErr" style="display:contents" hidden><span style="font-size:13px;font-weight:600;color:#B91C1C;margin-top:-6px">{{ $locErr ?? '' }}</span></div>
        <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding-top:12px;border-top:1px solid #F3F4F6;flex-wrap:wrap"><span style="font-size:13px;color:#4B5563">Now: <b style="color:#111827">{{ $locLabel ?? '' }}</b> · {{ $locNote ?? '' }}</span><button data-act="useGps" style="border:0;background:transparent;padding:0;font-size:13px;font-weight:700;color:#C2410C;cursor:pointer;min-height:32px">{{ $gpsLabel ?? '' }}</button></div>
      </div>
    </div>
  </div>
</div>

